import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { GovernanceStore } from '../dist/src/persistence.js';
import { CLP001Adapter } from '../dist/src/adapter.js';
import { authorizeTransition, evaluateEligibility, hashCanonical } from '../input/BUILD-CLP-001-B/dist/src/index.js';

const policy=JSON.parse(fs.readFileSync(new URL('../input/BUILD-CLP-001-B/input/BUILD-CLP-001-A/fixtures/transition-policy.json', import.meta.url),'utf8'));
const workers=JSON.parse(fs.readFileSync(new URL('../input/BUILD-CLP-001-B/input/BUILD-CLP-001-A/fixtures/workers.json', import.meta.url),'utf8'));
function ev(version,event_type,decision=null){const payload={event_id:`evt-${version}`,event_type,occurred_at:`2026-10-04T00:0${version}:00.000Z`,actor_id:'SYSTEM',actor_type:'SYSTEM',aggregate_id:'CASE-1',aggregate_version:version,causation_event_id:version===1?null:`evt-${version-1}`,correlation_id:'corr-1',input_refs:[],output_refs:[],source_refs:[],policy_refs:['CLP-001-TRANSITIONS@1.0.0'],evidence_refs:[],decision,reason_code:null};return {...payload,event_hash:hashCanonical(payload)};}
function adapter(){return new CLP001Adapter(new GovernanceStore(),policy,{authorizeTransition,evaluateEligibility});}

test('adapter permits a listed transition only when frozen guards pass',()=>{
  const a=adapter();
  const result=a.executeTransition({command_id:'cmd-1',from:'REPORTED',to:'INTAKE_STRUCTURED',event:ev(1,'IssueIntakeStructured','INTAKE_STRUCTURED'),satisfied_guards:['resident_origin_evidence_present']});
  assert.equal(result.status,'APPENDED');
});

test('direct API cannot bypass an unlisted transition',()=>{
  const a=adapter();
  assert.throws(()=>a.executeTransition({command_id:'cmd-x',from:'IN_PROGRESS',to:'VERIFIED',event:ev(1,'RepairVerified','VERIFIED'),satisfied_guards:['v1_v8_all_pass','verifier_independent','task_pack_hash_matches']}),/UNLISTED_TRANSITION/);
});

test('missing transition guard fails closed before persistence',()=>{
  const a=adapter();
  assert.throws(()=>a.executeTransition({command_id:'cmd-1',from:'REPORTED',to:'INTAKE_STRUCTURED',event:ev(1,'IssueIntakeStructured','INTAKE_STRUCTURED'),satisfied_guards:[]}),/GUARD_FAILED/);
  assert.equal(a.getEvents('corr-1').length,0);
});

test('AI recommendation cannot override deterministic worker ineligibility',()=>{
  const a=adapter();
  const workerB=workers.find(x=>x.worker_id==='WORKER-B');
  const result=a.evaluateWorker(workerB,{aiRecommendation:'ELIGIBLE'});
  assert.equal(result.decision,'INELIGIBLE_CAPABILITY');
});

test('completion cannot be persisted as verification',()=>{
  const a=adapter();
  assert.throws(()=>a.executeTransition({command_id:'cmd-z',from:'IN_PROGRESS',to:'VERIFIED',event:ev(1,'CompletionEvidenceSubmitted','VERIFIED'),satisfied_guards:['required_completion_evidence_present','no_stop_condition_active']}),/UNLISTED_TRANSITION/);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {
  buildGoldenCase, InMemoryGovernanceRepository, replayGoldenCase,
  verifyEventChain, issueCertification, canonicalize, hashCanonical,
  REQUIRED_ACCEPTANCE_IDS, REQUIRED_ADVERSARIAL_IDS
} from '../dist/src/index.js';

test('C-RED-001 builds exactly one closed golden case', () => {
  const g=buildGoldenCase();
  assert.equal(g.correlation_id,'corr_CLP001_GOLDEN_001');
  assert.equal(g.final_state,'CLOSED');
  assert.equal(g.events[0].event_type,'ResidentIssueReported');
  assert.equal(g.events.at(-1).event_type,'CaseClosed');
});

test('C-RED-002 append-only repository replays from correlation id only',()=>{
  const g=buildGoldenCase(); const repo=new InMemoryGovernanceRepository(); repo.persistGoldenCase(g);
  const r=replayGoldenCase(g.correlation_id, repo);
  assert.equal(r.final_state,'CLOSED');
  assert.equal(r.correlation_id,g.correlation_id);
  assert.equal(r.events.length,g.events.length);
  assert.ok(r.resolved_versions['AUTH-MN-504B161@1.0.0']);
  assert.ok(r.resolved_versions['AUTH-APPLEVALLEY-PLUMBING@CLP-FIXTURE-1']);
  assert.ok(r.resolved_versions['TASKPACK-CLP-001@1.0.0']);
});

test('C-RED-003 event-chain detects deletion and reordering',()=>{
  const g=buildGoldenCase();
  assert.equal(verifyEventChain(g.events,g.event_chain).valid,true);
  assert.equal(verifyEventChain(g.events.slice(1),g.event_chain).valid,false);
  const reversed=[...g.events].reverse();
  assert.equal(verifyEventChain(reversed,g.event_chain).valid,false);
});

test('C-RED-004 self-hash is canonical and excludes event_hash itself',()=>{
  const g=buildGoldenCase(); const e=g.events[0];
  const copy={...e}; delete copy.event_hash;
  assert.equal(e.event_hash,hashCanonical(copy));
  assert.equal(canonicalize({b:2,a:1}),canonicalize({a:1,b:2}));
});

test('C-RED-005 certification refuses missing frozen acceptance result',()=>{
  const g=buildGoldenCase();
  const acceptance=REQUIRED_ACCEPTANCE_IDS.slice(1).map(id=>({id,status:'PASS'}));
  const adversarial=REQUIRED_ADVERSARIAL_IDS.map(id=>({id,status:'PASS'}));
  assert.throws(()=>issueCertification(g,{acceptance,adversarial,implementation_commit:null}),/certification refused/i);
});

test('C-RED-006 certification refuses lineage or chain failure',()=>{
  const g=buildGoldenCase(); g.lineage_nodes.push({id:'BROKEN',parents:['NOPE']});
  const acceptance=REQUIRED_ACCEPTANCE_IDS.map(id=>({id,status:'PASS'}));
  const adversarial=REQUIRED_ADVERSARIAL_IDS.map(id=>({id,status:'PASS'}));
  assert.throws(()=>issueCertification(g,{acceptance,adversarial,implementation_commit:null}),/certification refused/i);
});

test('C-RED-007 complete golden case issues machine-verifiable certification',()=>{
  const g=buildGoldenCase();
  const acceptance=REQUIRED_ACCEPTANCE_IDS.map(id=>({id,status:'PASS'}));
  const adversarial=REQUIRED_ADVERSARIAL_IDS.map(id=>({id,status:'PASS'}));
  const cert=issueCertification(g,{acceptance,adversarial,implementation_commit:null});
  assert.equal(cert.spec_version,'1.0.0');
  assert.equal(cert.kap_version,'1.0.0');
  assert.equal(cert.event_count,g.events.length);
  assert.equal(cert.evidence_count,g.evidence.length);
  assert.equal(cert.certification_status,'CERTIFIED_WITH_PENDING_COMMIT_BINDING');
  assert.match(cert.replay_hash,/^sha256:[0-9a-f]{64}$/);
  assert.match(cert.certification_hash,/^sha256:[0-9a-f]{64}$/);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { GovernanceStore } from '../dist/src/persistence.js';
import { hashCanonical } from '../dist/src/index.js';

function event(overrides={}) {
  const payload={
    event_id:'evt-1', event_type:'ResidentIssueReported', occurred_at:'2026-10-04T00:00:00.000Z',
    actor_id:'RESIDENT-1', actor_type:'RESIDENT', aggregate_id:'CASE-1', aggregate_version:1,
    causation_event_id:null, correlation_id:'corr-1', input_refs:[], output_refs:[], source_refs:[],
    policy_refs:[], evidence_refs:[], decision:null, reason_code:null, ...overrides
  };
  const {event_hash:ignored,...hashPayload}=payload;
  return {...payload,event_hash:overrides.event_hash ?? hashCanonical(hashPayload)};
}

test('duplicate event_id with identical payload is idempotent', () => {
  const store = new GovernanceStore();
  const first = store.appendEvent(event(), 'cmd-1');
  const second = store.appendEvent(event(), 'cmd-1');
  assert.equal(first.status, 'APPENDED');
  assert.equal(second.status, 'IDEMPOTENT_REPLAY');
  assert.equal(store.eventsByCorrelation('corr-1').length, 1);
});

test('competing writers for same aggregate version allow exactly one event', () => {
  const store = new GovernanceStore();
  store.appendEvent(event(), 'cmd-a');
  assert.throws(
    () => store.appendEvent(event({event_id:'evt-2'}), 'cmd-b'),
    /aggregate version conflict/
  );
  assert.equal(store.eventsByCorrelation('corr-1').length, 1);
});

test('event append requires strict monotonic +1 aggregate version', () => {
  const store = new GovernanceStore();
  assert.throws(() => store.appendEvent(event({aggregate_version:2}), 'cmd-a'), /expected aggregate version 1/);
});

test('evidence is immutable and duplicate identical writes are idempotent', () => {
  const store = new GovernanceStore();
  const evidence = {evidence_id:'ev-1', content_hash:'sha256:abc', parent_evidence_ids:[], payload:{x:1}};
  assert.equal(store.appendEvidence(evidence).status, 'APPENDED');
  assert.equal(store.appendEvidence(evidence).status, 'IDEMPOTENT_REPLAY');
  assert.throws(() => store.appendEvidence({...evidence, payload:{x:2}}), /immutable evidence conflict/);
});

test('version records are immutable by reference', () => {
  const store = new GovernanceStore();
  assert.equal(store.pinVersion('AUTH@1', {hash:'sha256:a'}).status, 'APPENDED');
  assert.equal(store.pinVersion('AUTH@1', {hash:'sha256:a'}).status, 'IDEMPOTENT_REPLAY');
  assert.throws(() => store.pinVersion('AUTH@1', {hash:'sha256:b'}), /immutable version conflict/);
});


test('event with malformed self-hash is rejected at append time',()=>{
  const store=new GovernanceStore();
  assert.throws(()=>store.appendEvent(event({event_hash:'sha256:forged'}),'cmd-bad'),/event self-hash mismatch/);
});

