function adapter(){return new CLP001Adapter(new GovernanceStore(),policy,{authorizeTransition,evaluateEligibility});}
function ev(){const p={event_id:'evt-1',event_type:'IssueIntakeStructured',occurred_at:'2026-10-04T00:01:00.000Z',actor_id:'SYSTEM',actor_type:'AI',aggregate_id:'CASE-1',aggregate_version:1,causation_event_id:null,correlation_id:'corr-1',input_refs:[],output_refs:[],source_refs:[],policy_refs:['CLP-001-TRANSITIONS@1.0.0'],evidence_refs:[],decision:'INTAKE_STRUCTURED',reason_code:null};return {...p,event_hash:hashCanonical(p)};}

test('query surface exposes derived case state without mutable projection state',()=>{
