 a.executeTransition({command_id:'q1',from:'REPORTED',to:'INTAKE_STRUCTURED',event:ev(),satisfied_guards:['resident_origin_evidence_present']});
 assert.equal(a.getCaseState('corr-1'),'INTAKE_STRUCTURED');
