 a.appendEvidence({evidence_id:'ev-1',content_hash:'sha256:x',parent_evidence_ids:[],payload:{x:1}});
 a.appendLineageNode({id:'ev-1',parents:[]});
 assert.equal(a.getEvidence().length,1);
 assert.deepEqual(a.getLineage(),[{id:'ev-1',parents:[]}]);
});

test('certification records are immutable and queryable',()=>{
 const a=adapter();
 const cert={certification_id:'CLP001Certification',certification_hash:'sha256:abc',implementation_commit:'G0'};
 assert.equal(a.appendCertification(cert).status,'APPENDED');
 assert.equal(a.appendCertification(cert).status,'IDEMPOTENT_REPLAY');
 assert.throws(()=>a.appendCertification({...cert,implementation_commit:'FORGED'}),/immutable certification conflict/);
 assert.deepEqual(a.getCertification('CLP001Certification'),cert);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { buildGoldenCase, InMemoryGovernanceRepository, replayGoldenCase } from '../dist/src/index.js';
import { GovernanceStore } from '../dist/src/persistence.js';
import { replayPersistedCase } from '../dist/src/adapter.js';

function populatedStore(){
  const g=buildGoldenCase();
  const store=new GovernanceStore();
  for(const e of g.evidence) store.appendEvidence(e);
  for(const [ref,v] of Object.entries(g.versions)) store.pinVersion(ref,v);
  for(const c of g.event_chain) store.appendChainRecord(c);
  for(const n of g.lineage_nodes) store.appendLineageNode(n);
  for(const e of g.events) store.appendEvent(e,`cmd-${e.event_id}`);
  return {g,store};
}

test('cold restart replay produces identical historical replay hash',()=>{
  const {g,store}=populatedStore();
  const expectedRepo=new InMemoryGovernanceRepository(); expectedRepo.persistGoldenCase(g);
  const expected=replayGoldenCase(g.correlation_id,expectedRepo);
  const restarted=GovernanceStore.fromSnapshot(store.snapshot());
  const actual=replayPersistedCase(g.correlation_id,restarted);
  assert.equal(actual.replay_hash,expected.replay_hash);
  assert.equal(actual.event_chain_root,expected.event_chain_root);
});

test('persisted event tampering is detected before replay',()=>{
  const {g,store}=populatedStore();
  const snap=store.snapshot();
  snap.events[5].decision='FORGED';
  const tampered=GovernanceStore.fromSnapshot(snap);
  assert.throws(()=>replayPersistedCase(g.correlation_id,tampered),/event self-hash mismatch/);
});

test('persisted evidence tampering is detected before replay',()=>{
  const {g,store}=populatedStore();
  const snap=store.snapshot();
  snap.evidence[2].content={issue_class:'FORGED'};
  const tampered=GovernanceStore.fromSnapshot(snap);
  assert.throws(()=>replayPersistedCase(g.correlation_id,tampered),/evidence hash mismatch/);
});

test('missing pinned version fails replay closed',()=>{
  const {g,store}=populatedStore();
  const snap=store.snapshot();
  delete snap.versions['CLP-001-TRANSITIONS@1.0.0'];
  const tampered=GovernanceStore.fromSnapshot(snap);
  assert.throws(()=>replayPersistedCase(g.correlation_id,tampered),/missing pinned version/);
});

test('broken persisted chain ordering is detected',()=>{
  const {g,store}=populatedStore();
  const snap=store.snapshot();
  [snap.chain[3],snap.chain[4]]=[snap.chain[4],snap.chain[3]];
  const tampered=GovernanceStore.fromSnapshot(snap);
  assert.throws(()=>replayPersistedCase(g.correlation_id,tampered),/event chain invalid/);
});
